'use strict';
let helpIntent='understand',gentleAttempt=null,lastGentleResponse=null,stepDraft='';
const helpIntents=[['understand','Samajhna hai','Understand this feeling'],['calm','Thoda calm hona hai','Make room for a pause'],['step','Ek chhota step chahiye','One manageable action']];
function helpIntentChoices(){return `<section class="help-intent"><h2>Abhi kis tarah ka saath?</h2><div class="intent-choices">${helpIntents.map(([id,label,english])=>`<button class="chip ${helpIntent===id?'selected':''}" data-help-intent="${id}" aria-pressed="${helpIntent===id}"><strong>${label}</strong><span class="hinglish">${english}</span></button>`).join('')}</div><p class="small">Badal sakte ho. Koi sahi choice nahi.</p></section>`}
function supportForNow(){const m=currentMood();return `${button('‹ Refine the feeling','go-refine','back')}<p class="greeting">A starting point, chosen by you</p><h1>${helpIntent==='calm'?'Pehle thodi jagah.':helpIntent==='step'?'Bas agla chhota kadam.':'A little room around this feeling.'}</h1><div class="panel"><strong>${selected.map(id=>esc(moodData.find(x=>x.id===id)?.name||id)).join(' + ')||'Still finding the words'}</strong>${hi(m.hi)}${nuance?`<p>${esc(nuance)}</p>`:''}<p class="small">Intensity: ${intensity}/5. Your words, yours to change.</p></div>${helpIntentChoices()}${helpIntent==='understand'?`${understandingReflection()}<button class="choice soft" data-go="mind"><span class="symbol">≋</span><span><strong>Put it in my second mind</strong><small>Dump it first. Sort it only if you want.</small></span></button>${passageRecommendations()}`:helpIntent==='calm'?`<div class="panel"><h2>No need to solve this yet.</h2><p>Notice the room around you, or choose something familiar. Stop if it feels uncomfortable.</p></div><button class="choice" data-action="start-reset"><span class="symbol">≈</span><span><strong>A quiet reset</strong><small>Eyes open, senses optional. Your pace.</small></span></button>${comfortPanel()}`:`<div class="panel"><h2>What can be smaller?</h2><p>Could one thing wait, one request be clearer, or one person share the load? You choose.</p><label class="field" for="gentle-step">One step, in your words (optional)</label><input id="gentle-step" maxlength="200" value="${esc(stepDraft)}" placeholder="For example: ask for more time"><button class="secondary" data-gentle="try-step">Try this step</button><button class="text-btn" data-gentle="anchor-step">Keep this step in my anchors</button></div><a class="install-link" href="#mind">I need to put the thoughts somewhere first</a>`}<a class="install-link" href="#skills">Explore a psychology-informed skill</a>${pastHelpPanel(true)}${helpIntent==='calm'?'':comfortPanel()}${gentleAttempt?`<a class="install-link" href="#after">Come back to my gentle follow-up</a>`:''}${button('Log this moment with more detail','new-checkin','secondary')}${button('A story journey, maybe?','go-play','secondary')}${button('I need more support','go-help','text-btn')}`}
function startGentleAttempt(activity,detail='',extra={}){gentleAttempt={id:personalId(),at:new Date().toISOString(),moods:selected.length?[...selected]:['unsure'],intensity,need:feltNeed||'',nuance:nuance||'',activity,activityDetail:detail,...extra};lastGentleResponse=null;return gentleAttempt}
function gentleFollowup(){if(!gentleAttempt)return `<h1>No check-in waiting.</h1><p class="sub">Try a reset, reading, story, or something from your comfort shelf. A follow-up is always optional.</p><a class="install-link" href="#support">Choose what fits now</a>`;return `<a class="install-link" href="#support">‹ My choices</a><h1>Ab kaisa lag raha hai?</h1><p class="sub">After ${esc(gentleAttempt.activityDetail||nameFor(activityChoices,gentleAttempt.activity))}. Take your time; there’s no timer.</p><p class="note">Tapping below saves one check-in on this device, with your selected feelings and this action. This is your felt change, not a measurement or proof of what caused it. For your history: lighter marks helpful, same stays unsure, heavier marks not helpful. That does not establish cause.</p><div class="followup-choices">${[['lighter','Thoda halka','A little lighter'],['same','Same sa','About the same'],['heavier','Aur heavy','Heavier than before']].map(([id,label,en])=>`<button class="choice ${id==='lighter'?'':'soft'}" data-gentle-response="${id}"><span><strong>${label}</strong><small>Save: ${en}</small></span></button>`).join('')}</div><button class="text-btn" data-gentle="skip-followup">Skip without saving</button><p class="small">You can edit or remove the saved entry in My month. If something feels worse, you can stop and choose support.</p>`}
function gentleReceipt(){return `<h1>Bas itna kaafi hai.</h1><p class="sub">Your response is saved in My month. No need to explain more.</p>${lastGentleResponse==='heavier'?'<div class="panel"><h2>We can leave that here.</h2><p>You don’t have to repeat something that felt heavier. Try something familiar, or reach out to someone you trust.</p><a class="install-link" href="#comfort">My comfort shelf</a><a class="install-link" href="#help">Find more support</a></div>':''}<a class="install-link" href="#month">View or edit this check-in</a><br><a class="install-link" href="#home">Back to my space</a>`}
function saveGentleResponse(response){const attempt=gentleAttempt;if(!attempt)return;const entry={id:attempt.id,at:attempt.at,kind:attempt.moods.some(id=>!['okay','unsure'].includes(id))?'difficult':'followup',moods:attempt.moods,intensity:attempt.intensity,need:attempt.need,nuance:attempt.nuance,situation:'unsure',minutes:0,durationKnown:false,activity:attempt.activity,activityDetail:attempt.activityDetail,outcome:AntarPersonal.responseOutcome(response),feltChange:response,excerptId:attempt.excerptId||'',comfortId:attempt.comfortId||'',note:''};if(!commitCheckins([...checkins,entry]))return;gentleAttempt=null;lastGentleResponse=response;monthOffset=0;monthDay=AntarPatterns.dateKey(new Date(entry.at));logFilters={mood:'any',need:'any',situation:'any',outcome:'any',q:'',from:'',to:''};historyEvidenceIds=null;go('after-saved')}
document.addEventListener('input',event=>{if(event.target.id==='gentle-step')stepDraft=event.target.value});
document.addEventListener('click',event=>{const el=event.target.closest('button');if(!el)return;if(el.dataset.gentle==='reset-followup'){if(!gentleAttempt)startGentleAttempt('reset','A quiet reset');go('after');return}if(el.dataset.journeyCheckin){const f=fables.find(x=>x.id===el.dataset.journeyCheckin);if(f){startGentleAttempt('story',f.title);go('after')}return}if(el.dataset.journeyStep){saveAnchor(el.dataset.journeyStep);return}if(el.dataset.readingCheckin){const entry=excerptBank?.find(x=>x.id===el.dataset.readingCheckin);if(entry){startGentleAttempt('reflection',entry.heading,{excerptId:entry.id});go('after')}return}if(el.dataset.memoryCheckin){const group=memoryGroupCache.get(el.dataset.memoryCheckin);if(group){startGentleAttempt(group.activity,group.activityDetail||nameFor(activityChoices,group.activity),{excerptId:group.excerptId||'',comfortId:group.comfortId||''});go('after')}return}if(el.dataset.helpIntent){helpIntent=el.dataset.helpIntent;readingNeed=helpIntent==='step'?'action':helpIntent==='calm'?'comfort':'understanding';render(true);return}if(el.dataset.gentleResponse){saveGentleResponse(el.dataset.gentleResponse);return}if(el.dataset.gentle==='skip-followup'){gentleAttempt=null;go('home');return}if(el.dataset.gentle==='try-step'){if(!stepDraft.trim())return toast('Choose a small step, or use your second mind instead.');startGentleAttempt('other',stepDraft.trim());go('after')}if(el.dataset.gentle==='anchor-step'){if(stepDraft.trim())saveAnchor(stepDraft.trim());else toast('Add a few words first.')}if(el.dataset.action==='start-reset')startGentleAttempt('reset','A quiet reset');});
